WITH metrics AS (SELECT *, NTILE(4) OVER (PARTITION BY city, region ORDER BY sqft DESC, id) AS sqft_bucket, NTILE(4) OVER (PARTITION BY city, region ORDER BY sqft, id) AS sqft_bucket_2 FROM stores) SELECT CASE WHEN sqft_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END AS sqft_bucket_tier, COUNT_IF(region = 'South') AS south_events, COUNT(DISTINCT region) AS distinct_regions, SORT_ARRAY(COLLECT_SET(region)) AS region_list, SUM(CASE WHEN city = 'Tokyo' THEN sqft_bucket_2 ELSE 0 END) AS tokyo_sqft_bucket_2, COUNT(*) FILTER (WHERE city = 'London') AS london_rows, COUNT(CASE WHEN region = 'Central' THEN 1 END) AS central_count, GROUPING(CASE WHEN sqft_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END) AS grouping_level FROM metrics GROUP BY ROLLUP (CASE WHEN sqft_bucket >= 8 THEN 'HIGH' ELSE 'LOW' END) ORDER BY distinct_regions DESC NULLS FIRST
